import {journeysForPerson} from './document-model.mjs';
import {vehicleKey,vehicleForPerson} from './transport.mjs';
const month={gener:1,enero:1,jan:1,febrer:2,febrero:2,feb:2,marc:3,marzo:3,mar:3,abril:4,abr:4,apr:4,maig:5,mayo:5,may:5,juny:6,junio:6,jun:6,juliol:7,julio:7,jul:7,agost:8,agosto:8,ago:8,aug:8,setembre:9,septiembre:9,sep:9,set:9,octubre:10,oct:10,novembre:11,noviembre:11,nov:11,desembre:12,diciembre:12,dic:12,dec:12};
export function dateParts(value){const s=String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const iso=s.match(/(\d{4})-(\d{2})-(\d{2})/),numeric=s.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/),word=s.match(/(\d{1,2})\s+(?:de\s+)?([a-z]+)\.?\s*(\d{4})?/),time=s.match(/(\d{1,2}):(\d{2})/);let date='';if(iso)date=iso[1]+'-'+iso[2]+'-'+iso[3];else if(numeric)date=numeric[3]+'-'+numeric[2].padStart(2,'0')+'-'+numeric[1].padStart(2,'0');else if(word&&month[word[2]])date=(word[3]||'any-pendent')+'-'+String(month[word[2]]).padStart(2,'0')+'-'+word[1].padStart(2,'0');return {date,time:time?time[1].padStart(2,'0')+':'+time[2]:'',minutes:time?Number(time[1])*60+Number(time[2]):null};}
const airport=s=>String(s||'').trim().toUpperCase();
export function pickupGroups(trip){const groups=new Map();for(const p of trip.people){if(p.travelMode==='Cotxe')continue;const flights=journeysForPerson(trip,p.id).filter(s=>s.destination);const firstDate=dateParts(flights[0]?.departure).date;for(let i=0;i<flights.length;i++){const s=flights[i],arr=dateParts(s.arrival),dep=dateParts(s.departure),next=flights[i+1],nextDep=dateParts(next?.departure);if(next&&airport(next.origin)===airport(s.destination)&&arr.date&&arr.date===nextDep.date&&arr.minutes!==null&&nextDep.minutes!==null&&nextDep.minutes>=arr.minutes&&nextDep.minutes-arr.minutes<720)continue;const direction=dep.date&&dep.date===(trip.start||firstDate)?'Anada':dep.date&&firstDate&&dep.date!==firstDate?'Tornada':'Anada';const key=[direction,airport(s.destination),arr.date||'Data pendent',arr.time?arr.time.slice(0,2)+':00':'Hora pendent'].join('|');if(!groups.has(key))groups.set(key,{id:key,direction,airport:s.destination,date:arr.date||'Data pendent',hour:arr.time?arr.time.slice(0,2)+':00':'Hora pendent',people:[]});const g=groups.get(key);if(!g.people.some(x=>x.person.id===p.id&&x.flight.service===s.service))g.people.push({person:p,flight:s,vehicle:vehicleForPerson(trip,p,direction)});}}
return [...groups.values()].sort((a,b)=>(a.date+a.hour+a.airport).localeCompare(b.date+b.hour+b.airport));}
export function pickupsHTML(trip,esc){const groups=pickupGroups(trip);return `<div class="section-head"><div><h2>Recollides a l’aeroport</h2><p>Arribades agrupades per aeroport, data i franja d’una hora. Les escales amb connexió no generen recollides.</p></div><button class="button secondary" data-action="new-vehicle">＋ Vehicle</button></div>${groups.length?groups.map((g,index)=>`<section class="panel pickup-group"><div class="section-head"><div><span class="pill">${esc(g.direction)}</span><h3>${esc(g.airport)} · ${esc(g.date)} · ${esc(g.hour)}</h3><p>${g.people.length} persones · ${g.people.filter(x=>!x.vehicle).length} sense vehicle</p></div><button class="button" data-action="assign-pickup" data-id="${index}">Assignar furgo</button></div><div class="table-wrap"><table><thead><tr><th>PERSONA</th><th>VOL / ARRIBADA</th><th>VEHICLE / CONDUCTOR</th></tr></thead><tbody>${g.people.map(({person:p,flight:s,vehicle:v})=>`<tr><td>${esc(p.name)}</td><td>${esc(s.service||'Vol pendent')}<small>${esc(s.arrival||'Hora pendent')}</small></td><td>${v?`${esc(v.name)}<small>${esc(v.driver||'Conductor pendent')}</small>`:'<span class="status">Sense assignar</span>'}</td></tr>`).join('')}</tbody></table></div></section>`).join(''):'<div class="empty"><h3>Encara no hi ha arribades detectades</h3><p>Llegeix els documents i associa els vols als participants.</p></div>'}<section class="panel"><h3>Places dels vehicles</h3>${trip.vehicles.length?trip.vehicles.map(v=>{const used=trip.people.filter(p=>p[vehicleKey(v.direction)]===v.id).length;return `<p><strong>${esc(v.name)}</strong> · ${esc(v.direction)} · ${used}/${v.seats||'?'} passatgers · ${v.seats?Math.max(0,v.seats-used)+' places lliures':'Capacitat pendent'} · ${esc(v.driver||'Conductor pendent')}</p>`}).join(''):'<p>Crea els vehicles per assignar les recollides.</p>'}</section>`;}
